sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api
}) {
    var arr = [];
    var results_daily = api.data.verticalC_headlinemetric2_daily.output.result;
    var results_monthly = api.data.verticalC_headlinemetric2_monthly.output.result;

    const clientStateParameter = api.state.Tab11stBreakdown;

    // Get daily and monthly frequency lists
    const dailyFrequency = api.state.elementsDeploymentFrequencyDaily;
    const monthlyFrequency = api.state.elementsDeploymentFrequencyMonthly;

    // Get their lengths
    const dailyLength = dailyFrequency.length;
    const monthlyLength = monthlyFrequency.length;

    for (let i = 0; i < dailyLength; i++) {
        arr.push('platinum');
    }

    // Step 2: Generate a mask marking intersections (1 for match, 0 for non-match)
    const intersectionMask = monthlyFrequency.map(pis => dailyFrequency.includes(pis) ? 1 : 0);
    const zeroCount = intersectionMask.filter(value => value === 0).length;
    for (let k = 0; k < zeroCount; k++) {
        arr.push('green');
    }

    return arr;


    // var clientStateParameter2 = 'verticalCMetric2ShowHealth';
    // api.setState(clientStateParameter2, arr);
}
